style.css:
@-moz-document domain("downloads.khinsider.com") {
/* ============================================================
     KHInsider Dark
     The KHInsider archive (downloads.khinsider.com) is a classic
     server-rendered site with hardcoded light colors and no CSS
     custom properties, so the theme overrides per element: the
     two-column shell, the beveled sidebar module heads, the song
     /album-list tables (tan headers), the HTML5 audio player bar,
     search results, the comment threads and the legacy forms.
     Semantic reds (donate / attention) are preserved; the player
     progress + comment CTA keep a tuned, readable accent.
     ============================================================ */

  :root { color-scheme: dark !important; }

  /* ---- Base shell ---- */
  html, body {
    background-color: #14181d !important;
    background-image: none !important;
    color: #e6edf3 !important;
  }
  #container { background-color: #14181d !important; border-color: #262c33 !important; }
  #rightColumn { background-color: #14181d !important; }
  #pageContent { background-color: #14181d !important; color: #e6edf3 !important; }
  #leftColumn { background-color: #1c2128 !important; }

  /* Soften the hard light borders the layout draws between columns */
  #pageContent, #leftColumn, #rightColumn,
  #pageContent div, #homepagePopularSeries, #homepageLatestSoundtracks {
    border-color: #262c33 !important;
  }

  /* ---- Sidebar logo + navigation ---- */
  #leftColumn h1, #leftColumn h1 a { color: #e6edf3 !important; }

  /* Beveled module heads ship a light gradient image — flatten to dark */
  #leftColumn h3 {
    background-color: #0d1117 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }
  #leftColumn ul li a { color: #c4cdd6 !important; }
  #leftColumn ul li a:hover { color: #9bd4ff !important; }
  /* raw red star/heart accent icons -> softened red, more legible on dark */
  #leftColumn .material-icons { color: #ff7b72 !important; }

  /* ---- Headings + body text ---- */
  h1, h2, h3, h4, h5 { color: #e6edf3 !important; }
  #pageContent p,
  #pageContent li,
  #pageContent b,
  #pageContent span,
  #pageContent div,
  #homepageText,
  #homepageText p { color: #c4cdd6 !important; }

  /* ---- Links ---- */
  #pageContent a { color: #5fb0e6 !important; }
  #pageContent a:hover { color: #9bd4ff !important; }
  /* keep attention/donate reds legible without dumping raw #f00 */
  #pageContent a[href*="donat"],
  #pageContent font[color="red"],
  #pageContent .albumMassDownload a { color: #ff7b72 !important; }

  /* ---- Tables: album list, song list, search results ---- */
  #songlist, .albumList, .requestList, #pageContent table {
    background-color: transparent !important;
    border-color: #2d333b !important;
  }
  /* tan (#cccc99) header + total rows -> elevated dark */
  #songlist th, .albumList th, .requestList th,
  #songlist tr.header td, #songlist .clickable-row.collapsed,
  #songlist #songlist_footer td, #songlist tr#songlist_footer th {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  #songlist td, .albumList td, .requestList td {
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }
  #songlist tr td a, .albumList td a, .requestList td a { color: #5fb0e6 !important; }
  /* zebra + hover */
  #songlist tr:hover td,
  .albumList tr:hover td,
  .requestList tr:hover td { background-color: #1c2128 !important; }
  /* the song "Total:" footer row */
  #songlist tr:last-child td,
  #songlist tr:last-child th { background-color: #1c2128 !important; color: #e6edf3 !important; }
  /* table download / add-to-playlist glyphs (black originals) */
  #songlist .material-icons,
  .playlistDownloadSong .material-icons,
  .playlistAddTo .material-icons,
  .playTrack .material-icons { color: #c4cdd6 !important; }
  #songlist .material-icons:hover,
  .playlistDownloadSong .material-icons:hover,
  .playlistAddTo .material-icons:hover { color: #9bd4ff !important; }

  /* ---- Album art ---- */
  .albumImage img, .albumImage a { border-color: #2d333b !important; }

  /* ---- Native <audio> element (per-song download page) ----
     The song download page uses a real HTML5 <audio controls> that
     renders as a stark white default-Chrome pill — force its UA
     controls dark. (The custom .audioplayer widget is themed below.) */
  audio {
    color-scheme: dark !important;
    background-color: #1c2128 !important;
    border-radius: 8px !important;
  }

  /* ---- HTML5 audio player (custom widget) ---- */
  .audioplayer {
    background-color: #0d1117 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .audioplayer * { color: #e6edf3 !important; border-color: #2d333b !important; }
  .audioplayerTimeCurrent, .audioplayerTimeDuration { color: #c4cdd6 !important; }
  .audioplayer .material-icons { color: #e6edf3 !important; }
  /* progress track + played accent */
  .audioplayerBar {
    background-color: #1c2128 !important;
    background-image: none !important;
  }
  .audioplayerBarLoaded {
    background-color: #2d333b !important;
    background-image: none !important;
  }
  .audioplayerBarPlayed {
    background-color: #5fb0e6 !important;
    background-image: none !important;
  }
  /* volume popup + level */
  .audioplayerVolumeBar, .audioplayerVolumeBarPopup {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .audioplayerVolumeBarLevel {
    background-color: #5fb0e6 !important;
    background-image: none !important;
  }

  /* ---- Comments ---- */
  #news_comments, .comment_wrap { background-color: transparent !important; }
  .comment_message {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .comment_message a { color: #5fb0e6 !important; }
  /* speech-bubble pointer is a white raster triangle — tint it to the bubble color */
  .comment_graphic { filter: brightness(0.14) !important; }
  .quote {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .comments_headinggraphic, .comments_headinggraphic2 { color: #e6edf3 !important; }
  /* "+ Comment" CTA: original light-blue button -> tuned dark-blue, white text */
  .reply_to_comment a {
    background-color: #1f6feb !important;
    color: #ffffff !important;
  }
  #pageContent .reply_to_comment a font,
  #pageContent .reply_to_comment a span { color: #ffffff !important; }

  /* ---- Forms ---- */
  input[type="text"], input[type="search"], input[type="password"],
  input[type="email"], textarea, select {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="text"]::placeholder, textarea::placeholder { color: #8b949e !important; }
  input[type="submit"], input[type="button"], button {
    background-color: #1c2128 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }
  input[type="submit"]:hover, input[type="button"]:hover, button:hover {
    background-color: #262c33 !important;
  }

  /* ---- Cookie consent banner ---- */
  .cookieinfo {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }
  .cookieinfo a { color: #5fb0e6 !important; }
  .cookieinfo-close { color: #14181d !important; }

  /* ---- Scrollbar ---- */
  ::-webkit-scrollbar { width: 12px; height: 12px; }
  ::-webkit-scrollbar-track { background: #14181d; }
  ::-webkit-scrollbar-thumb { background: #2d333b; border-radius: 6px; }
  ::-webkit-scrollbar-thumb:hover { background: #3a4250; }
}

@-moz-document url-prefix("https://downloads.khinsider.com/forums") {
/* ============================================================
     KHInsider forum (XenForo)
     The /forums/ section runs a legacy XenForo skin with no runtime
     --xf-* HSL tokens, so its hardcoded light surfaces are themed
     per element: the header/nav chrome, section-link bar, category
     blocks + node rows, form rows, the post/thread surfaces and the
     footer. The archive block above (domain scope) already darkens
     the page base, native inputs and scrollbar; this block reskins
     the XenForo chrome the archive rules don't reach. Brand blue is
     kept for links and CTAs. */

  /* ---- Base surfaces (light XenForo wrappers -> dark) ---- */
  body, .p-pageWrapper, .p-body, #top {
    background-color: #14181d !important;
    color: #e6edf3 !important;
  }
  .p-body-content a, .p-body-sidebar a, .block a, .p-breadcrumbs a { color: #5fb0e6 !important; }
  .p-body-content a:hover, .block a:hover { color: #9bd4ff !important; }

  /* ---- Header / nav chrome (XenForo blue -> deep dark) ---- */
  .p-header, .p-nav, .p-nav-inner, .p-nav-list,
  .p-navSticky, .p-navSticky.is-sticky .p-nav {
    background-color: #0d1117 !important;
    background-image: none !important;
    border-color: #20262e !important;
  }
  .p-nav-opposite a, .p-navEl-link, .p-navgroup-link,
  .p-header-content a, .p-header-logo a { color: #c4d3e8 !important; }
  .p-navEl.is-selected > .p-navEl-link,
  .p-navEl-link:hover {
    color: #ffffff !important;
    background-color: #1c232c !important;
  }
  /* "Log in / Register" account pill ships a light-blue border */
  .p-navgroup.p-account .p-navgroup-link,
  .p-account a.p-navgroup-link--textual {
    color: #c4d3e8 !important;
    border-color: #2d333b !important;
  }

  /* ---- Section-links bar under the header ---- */
  .p-sectionLinks {
    background-color: #161b22 !important;
    border-color: #20262e !important;
  }
  .p-sectionLinks-list > li > a { color: #c4d3e8 !important; }
  .p-sectionLinks-list > li.is-selected > a {
    color: #ffffff !important;
    background-color: #1c232c !important;
  }

  /* ---- Breadcrumbs / page title ---- */
  .p-breadcrumbs li, .p-breadcrumbs a, .p-breadcrumbs:before { color: #aab4bf !important; }
  .p-title-value { color: #e6edf3 !important; }
  .p-description { color: #8b949e !important; }

  /* ---- Blocks / categories / node rows ---- */
  .block-container, .block-body, .block-row {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  /* category/section header ships a light gradient image */
  .block-header, .block-tabHeader, .block-minorTabHeader {
    background-image: linear-gradient(0deg, #161b22, #1c232c) !important;
    background-color: #1a2029 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .block-header a, .block-header .block-header-title { color: #e6edf3 !important; }
  .block-footer {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #aab4bf !important;
    border-color: #2d333b !important;
  }
  .structItem { border-color: #262c33 !important; }
  .structItem--thread:hover, .structItem.is-selected { background-color: #1c232c !important; }
  .structItem-minor, .structItem-parts,
  .structItem-cell--latest .structItem-minor { color: #aab4bf !important; }
  .node-extra, .node-meta, .node-statsMeta,
  .node-description, .node-descriptionText { color: #aab4bf !important; }
  .pairs dt { color: #8b949e !important; }
  .pairs dd { color: #c4cdd6 !important; }

  /* ---- Form rows (login / register / search) ---- */
  .formRow, .formRow > dt, .formRow > dd {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }
  .formRow > dt, .formRow-explain, .formRow-hint { color: #8b949e !important; }
  .inputGroup-text, .inputGroup--joined .input {
    background-color: #161b22 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .formSubmitRow, .formSubmitRow-bar {
    background-image: none !important;
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }

  /* ---- Inputs / buttons / placeholders ---- */
  .input, .input--date, .js-editor {
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .input:focus { background-color: #1a2029 !important; border-color: #3d6a96 !important; }
  .input::placeholder, .js-editor::placeholder { color: #8b949e !important; opacity: 1 !important; }
  .button, .menuTrigger, .buttonGroup {
    background-image: none !important;
    background-color: #21262d !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .button:hover { background-color: #2a313a !important; color: #ffffff !important; }
  .button.button--cta, .button--cta {
    background-image: none !important;
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  .button.button--cta:hover { background-color: #3b82f6 !important; }
  /* password-strength meter (register): native <meter> track is white */
  meter, .meterBar { background: #161b22 !important; border: 1px solid #2d333b !important; }
  meter::-webkit-meter-bar { background: #161b22 !important; border: none !important; }

  /* ---- Floating surfaces — keep opaque (no bleed-through) ---- */
  .menu, .menu-content, .tooltip-content, .overlay,
  .autoComplete {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  .menu-header, .menu-footer, .menu-footer-controls, .overlay-title {
    background-image: none !important;
    background-color: #161b22 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }
  /* menu link rows keep XenForo's default #141414 text -> dark-on-dark on the
     dark flyout; force a legible light color (and text-fill) */
  .menu-row, .menu-linkRow, .menu-row > a, .menu-linkRow > a {
    color: #c4d3e8 !important;
    -webkit-text-fill-color: #c4d3e8 !important;
    border-color: #2d333b !important;
  }
  .menu-row:hover, .menu-linkRow:hover,
  .menu-row > a:hover, .menu-linkRow:hover > a {
    background-color: #232a33 !important;
    color: #ffffff !important;
    -webkit-text-fill-color: #ffffff !important;
  }
  .offCanvasMenu-content, .offCanvasMenu-header {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }
  /* error / info notices */
  .blockMessage--error {
    background-color: #3a1d1f !important;
    color: #ff9a93 !important;
    border-color: #5a2b2e !important;
  }
  .blockMessage, .blockMessage--none, .blockMessage--info {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  /* inline field-validation tooltip bubble */
  .inputValidationError, .js-validationError {
    background-color: #3a1d1f !important;
    color: #ff9a93 !important;
    border-color: #5a2b2e !important;
  }

  /* ---- Messages / posts / quotes / code (thread view) ---- */
  .message, .message-cell, .message-inner { border-color: #2d333b !important; }
  .message-cell--user { background-color: #181d24 !important; }
  .message-name .username, .message-name a { color: #e6edf3 !important; }
  .message-userTitle, .message-attribution, .message-attribution a,
  .message-userExtras dd { color: #9aa4af !important; }
  .bbWrapper { color: #c8d1da !important; }
  blockquote.bbCodeBlock, .bbCodeBlock--quote,
  .bbCodeBlock-title, .bbCodeQuote-source {
    background-color: #181d24 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }
  .bbCodeCode, .bbCodeBlock--code .bbCodeBlock-content, pre, code, kbd {
    background-color: #0d1117 !important;
    color: #c9d1d9 !important;
    border-color: #2d333b !important;
  }

  /* ---- Pagination ----
     XenForo pages the list with a light default palette: the page <li>
     wrappers (#e8f4fc), the Next/Last jump buttons (light gradient) and
     the per-row "page N" jump pills (#fef4e7) all ship light. Darken the
     wrappers + buttons, not just the inner <a>. */
  .pageNav-page, .pageNav-page a,
  .pageNav-jump, .pageNavSimple-el {
    background-image: none !important;
    background-color: #1c2128 !important;
    color: #cdd6e0 !important;
    border-color: #2d333b !important;
  }
  .pageNav-page--current a, .pageNav-page--current {
    background-image: none !important;
    background-color: #1f6feb !important;
    color: #ffffff !important;
    border-color: #1f6feb !important;
  }
  .pageNav-jump, .pageNavSimple-el { color: #5fb0e6 !important; }
  /* per-row page-jump pills inside thread rows */
  .structItem-pageJump a {
    background-image: none !important;
    background-color: #21262d !important;
    color: #9bd4ff !important;
    border-color: #2d333b !important;
  }

  /* filter/sort bar above thread lists ships a light gradient strip */
  .block-filterBar, .filterBar {
    background-image: none !important;
    background-color: #161b22 !important;
    border-color: #2d333b !important;
  }
  .filterBar a, .filterBar-menuTrigger { color: #5fb0e6 !important; }

  /* standalone tab strip (What's new / member-profile tabs) ships a white bar */
  .tabs, .tabs--standalone {
    background-color: #161b22 !important;
    background-image: none !important;
    border-color: #2d333b !important;
  }
  .tabs-tab, .tabs-tab a { color: #c4d3e8 !important; }
  .tabs-tab.is-active, .tabs-tab.is-active a { color: #5fb0e6 !important; }
  .tabs-tab:hover { color: #9bd4ff !important; }

  /* ---- Footer ---- */
  .p-footer, .p-footer-inner, .p-footer-row {
    background-color: #0d1117 !important;
    color: #c4cdd6 !important;
    border-color: #20262e !important;
  }
  .p-footer a { color: #aab4bf !important; }

  /* avatars / image wrappers stay transparent (no white tile) */
  .avatar, .avatarWrapper, .contentRow-figure,
  .structItem-iconContainer { background-color: transparent !important; }
}
